macro_rules! deps {
    () => {
        IResult!();
        Err!();
        ErrorKind!();
        PResult!();
        Parser!();
        Error!();
        ParseError!();
        Needed!();
        OutputMode!();
    };
}

macro_rules! Input {
    () => {
        deps!();
        # [doc = " Parser input types must implement this trait"] pub trait Input : Clone + Sized { # [doc = " The current input type is a sequence of that `Item` type."] # [doc = ""] # [doc = " Example: `u8` for `&[u8]` or `char` for `&str`"] type Item ; # [doc = " An iterator over the input type, producing the item"] type Iter : Iterator < Item = Self :: Item > ; # [doc = " An iterator over the input type, producing the item and its byte position"] # [doc = " If we're iterating over `&str`, the position"] # [doc = " corresponds to the byte index of the character"] type IterIndices : Iterator < Item = (usize , Self :: Item) > ; # [doc = " Calculates the input length, as indicated by its name,"] # [doc = " and the name of the trait itself"] fn input_len (& self) -> usize ; # [doc = " Returns a slice of `index` bytes. panics if index > length"] fn take (& self , index : usize) -> Self ; # [doc = " Returns a slice starting at `index` bytes. panics if index > length"] fn take_from (& self , index : usize) -> Self ; # [doc = " Split the stream at the `index` byte offset. panics if index > length"] fn take_split (& self , index : usize) -> (Self , Self) ; # [doc = " Returns the byte position of the first element satisfying the predicate"] fn position < P > (& self , predicate : P) -> Option < usize > where P : Fn (Self :: Item) -> bool ; # [doc = " Returns an iterator over the elements"] fn iter_elements (& self) -> Self :: Iter ; # [doc = " Returns an iterator over the elements and their byte offsets"] fn iter_indices (& self) -> Self :: IterIndices ; # [doc = " Get the byte offset from the element's position in the stream"] fn slice_index (& self , count : usize) -> Result < usize , Needed > ; # [doc = " Looks for the first element of the input type for which the condition returns true,"] # [doc = " and returns the input up to this position."] # [doc = ""] # [doc = " *streaming version*: If no element is found matching the condition, this will return `Incomplete`"] fn split_at_position < P , E : ParseError < Self > > (& self , predicate : P) -> IResult < Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . position (predicate) { Some (n) => Ok (self . take_split (n)) , None => Err (Err :: Incomplete (Needed :: new (1))) , } } # [doc = " Looks for the first element of the input type for which the condition returns true"] # [doc = " and returns the input up to this position."] # [doc = ""] # [doc = " Fails if the produced slice is empty."] # [doc = ""] # [doc = " *streaming version*: If no element is found matching the condition, this will return `Incomplete`"] fn split_at_position1 < P , E : ParseError < Self > > (& self , predicate : P , e : ErrorKind ,) -> IResult < Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . position (predicate) { Some (0) => Err (Err :: Error (E :: from_error_kind (self . clone () , e))) , Some (n) => Ok (self . take_split (n)) , None => Err (Err :: Incomplete (Needed :: new (1))) , } } # [doc = " Looks for the first element of the input type for which the condition returns true,"] # [doc = " and returns the input up to this position."] # [doc = ""] # [doc = " *complete version*: If no element is found matching the condition, this will return the whole input"] fn split_at_position_complete < P , E : ParseError < Self > > (& self , predicate : P ,) -> IResult < Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . split_at_position (predicate) { Err (Err :: Incomplete (_)) => Ok (self . take_split (self . input_len ())) , res => res , } } # [doc = " Looks for the first element of the input type for which the condition returns true"] # [doc = " and returns the input up to this position."] # [doc = ""] # [doc = " Fails if the produced slice is empty."] # [doc = ""] # [doc = " *complete version*: If no element is found matching the condition, this will return the whole input"] fn split_at_position1_complete < P , E : ParseError < Self > > (& self , predicate : P , e : ErrorKind ,) -> IResult < Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . split_at_position1 (predicate , e) { Err (Err :: Incomplete (_)) => { if self . input_len () == 0 { Err (Err :: Error (E :: from_error_kind (self . clone () , e))) } else { Ok (self . take_split (self . input_len ())) } } res => res , } } # [doc = " mode version of split_at_position"] fn split_at_position_mode < OM : crate :: OutputMode , P , E : ParseError < Self > > (& self , predicate : P ,) -> crate :: PResult < OM , Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . position (predicate) { Some (n) => Ok ((self . take_from (n) , OM :: Output :: bind (| | self . take (n)))) , None => { if OM :: Incomplete :: is_streaming () { Err (Err :: Incomplete (Needed :: new (1))) } else { let len = self . input_len () ; Ok ((self . take_from (len) , OM :: Output :: bind (| | self . take (len)))) } } } } # [doc = " mode version of split_at_position"] fn split_at_position_mode1 < OM : crate :: OutputMode , P , E : ParseError < Self > > (& self , predicate : P , e : ErrorKind ,) -> crate :: PResult < OM , Self , Self , E > where P : Fn (Self :: Item) -> bool , { match self . position (predicate) { Some (0) => Err (Err :: Error (OM :: Error :: bind (| | { E :: from_error_kind (self . clone () , e) }))) , Some (n) => Ok ((self . take_from (n) , OM :: Output :: bind (| | self . take (n)))) , None => { if OM :: Incomplete :: is_streaming () { Err (Err :: Incomplete (Needed :: new (1))) } else { let len = self . input_len () ; if len == 0 { Err (Err :: Error (OM :: Error :: bind (| | { E :: from_error_kind (self . clone () , e) }))) } else { Ok ((self . take_from (len) , OM :: Output :: bind (| | self . take (len)))) } } } } } }
    };
}

Input!();